    a=ap.parse_args();rr=json.loads(a.route_receipt.read_text());cr=json.loads(a.cleanup_receipt.read_text());co=json.loads(a.connectivity.read_text());ng=json.loads(a.negative.read_text());ly=json.loads(a.layout.read_text());digest=sha(a.board);assert digest==cr['candidate_sha256']==co['board_sha256']==ng['source_sha256']==ly['source_board_sha256'];assert co['channel_count']==12 and co['actual_pin_checks']==156 and not co['pin_connectivity_errors']and co['open_local_nets']==0;assert not ly['failed_RTHR_channels']and not ly['role_mismatch_channels']and not ly['failed_2mm_bypass_channels'];assert all(x['all_twelve_real_copper_cuts_detected']for x in ng['negative_controls']);scope=set(rr['scope_refs']);assert len(scope)==72
    old=pcbnew.LoadBoard(str(a.base.resolve()));now=pcbnew.LoadBoard(str(a.board.resolve()));of={f.GetReference():f for f in old.GetFootprints()};nf={f.GetReference():f for f in now.GetFootprints()};assert set(of)==set(nf);changed=[]
