    paths=[a.base,a.board,a.route_receipt,a.cleanup_receipt,a.connectivity,a.negative,a.layout,ROOT/'hardware/motherboard_motors/design.json',ROOT/'research/digital-inputs/iso1212.pdf']+[ROOT/'tools'/n for n in ['hardware_motor_alarm_layout.py','hardware_build_motor_alarm_fixture_native.py','hardware_route_motor_alarm_cells_native.py','hardware_retire_motor_alarm_stubs_native.py','hardware_validate_motor_alarm_cells_native.py','hardware_test_motor_alarm_disconnect_native.py','hardware_freeze_motor_alarm_layout_native.py']]
    result=dict(revision='motor-alarm-layout-route-r01',source_board=str(a.base),source_board_sha256=sha(a.base),candidate_board=str(a.board),candidate_sha256=digest,source_schematic_changed=False,total_actual_footprints=len(nf),exact_72_pose_changes=changed,exact_removed_copper=rr['exact_removed_private_copper']+cr['exact_removed_old_alarm_copper'],exact_added_copper=rr['exact_added_copper'],exact_added_zones=rr['exact_added_zones'],removed_copper_count=len(remove),added_copper_count=len(add),added_zones=len(new_zones-old_zones),all_other_actual_pad_and_copper_identities_preserved=True,unchanged_observer_clusters_retained=cr['all_unchanged_observer_clusters_preserved'],observer_pads_checked=cr['observer_pads_checked'],actual_native_endpoint_checks=156,open_local_nets=0,all24_real_copper_cut_negative_controls_detected=True,actual_RTHR_external_clearance_min_mm=min(r['external_RTHR_native_pad_clearance_mm']for r in ly['channels']),actual_VCC_bypass_pad_centre_max_mm=max(r['vcc_pin_to_bypass_pad_centre_mm']for r in ly['channels']),native_regular_DRC_errors=sum(r['severity']=='error'for r in cr['native_remaining_violations']),remaining_native_warnings=cr['native_remaining_violations'],uncapped_whole_board_missing_joins=co['actual_uncapped_whole_board_missing_joins'],owned_existing_host_tests_passed=269,visual_actual_native_F_Cu_Fab_reviewed=True,conventional_new_vias_diameter_drill_mm=[.5,.2],all_new_vias_free_standing_auto_net_reassignment_disabled=True,global_IO3_feed_and_return_delivery_qualified=False,SUB_thermal_islands_owned_by_final_plane_integration=True,manufacturing_ready=False,files={str(p.resolve().relative_to(ROOT)if p.resolve().is_relative_to(ROOT)else p):sha(p)for p in paths})
    a.output.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items()if k not in('exact_72_pose_changes','exact_removed_copper','exact_added_copper','exact_added_zones','files','remaining_native_warnings')}))
